// Variable Definitions **********************************************************************************************************

// Signals 
let signals_alarm = global.get("GDB.signals.alarm") || 0;

// Signals - Energy
let signals_energyConsumptionFillingTank = global.get("GDB.signals.energySignals.energyConsumptionFillingTank") || 0;
let signals_waterConsumptionFillingTank = global.get("GDB.signals.energySignals.waterConsumptionFillingTank") || 0;
let signals_energyConsumptionHeatingTank = global.get("GDB.signals.energySignals.energyConsumptionHeatingTank") || 0;
let signals_energyConsumptionFillingBottle = global.get("GDB.signals.energySignals.energyConsumptionFillingBottles") || 0;
let signals_gasConsumptionHeatingTank = global.get("GDB.signals.energySignals.gasConsumptionHeatingTank") || 0;

// Signals - Tank
let signals_tankLevel = global.get("GDB.signals.tankSignals.actLevel") || 0;
let signals_tankMaxLevel = global.get("GDB.signals.tankSignals.maxLevel") || false; 
let signals_tankPressure = global.get("GDB.signals.tankSignals.actPressure") || 0; // Assuming this is in kPa
let signals_tankTemperature = global.get("GDB.signals.tankSignals.actTemperature") || 20;
let signals_tankMaxTemperature = global.get("GDB.signals.tankSignals.maxTemperature") || false;

// Convert tank pressure to hPa (assuming input in kPa)
let signals_tankPressure_hPa = signals_tankPressure * 10; 

// Signals - Bottle
let signals_bottleLevel = global.get("GDB.signals.bottleSignals.actLevel") || 0;
let signals_bottleMaxLevel = global.get("GDB.signals.bottleSignals.maxLevel") || false;
let signals_bottleOutputTank = global.get("GDB.signals.bottleSignals.outputTank") || 0;

// Operate
let operate_machineState = global.get("GDB.operate.machineState") || 0;

// Model
let model_cycleTime = global.get("GDB.model.cycleTime") || 0;

// Process
let process_productId = global.get("GDB.process.productId") || 0;
let process_numberProduced = global.get("GDB.process.numberProduced") || 0;
let process_numberFaulty = global.get("GDB.process.numberFaulty") || 0;
let process_numberGood = global.get("GDB.process.numberGood") || 0;
let process_batchId = global.get("GDB.process.batchId") || "A1"; // Static placeholder for batch ID

//Product
let serialNumber = global.get("GDB.serialNumber") || "";

// Helper Variables
const maxTankLevel = global.get("maxTankLevel") || 5000;
const maxBottleLevel = global.get("maxBottleLevel") || 1;
const maxTankTemperature = global.get("maxTankTemperature") || 80;
let shiftCounter = global.get("shiftCounter") || 0;

// Initialize state
let state = global.get("state") || "start";



// Payload Structure ******************************************************************************************************

const currentDate = new Date().toISOString();

const StateMsg = {
    payload: {
        "seq": 1000,
        "vals": [
            { "id": "101", "qc": 3, "ts": currentDate, "val": signals_tankLevel }, // Tank Level
            { "id": "102", "qc": 3, "ts": currentDate, "val": signals_tankMaxLevel }, // Tank Max Level
            { "id": "103", "qc": 3, "ts": currentDate, "val": signals_tankPressure_hPa }, // Tank Pressure (hPa)
            { "id": "104", "qc": 3, "ts": currentDate, "val": signals_tankTemperature }, // Tank Temperature
            { "id": "105", "qc": 3, "ts": currentDate, "val": signals_tankMaxTemperature }, // Tank Max Temperature
            { "id": "106", "qc": 3, "ts": currentDate, "val": signals_bottleLevel }, // Bottle Level
            { "id": "107", "qc": 3, "ts": currentDate, "val": signals_bottleMaxLevel }, // Bottle Max Level
            { "id": "108", "qc": 3, "ts": currentDate, "val": signals_bottleOutputTank }, // Bottle Output Tank
            { "id": "109", "qc": 3, "ts": currentDate, "val": signals_energyConsumptionFillingTank }, // Energy Consumption Filling Tank
            { "id": "110", "qc": 3, "ts": currentDate, "val": signals_waterConsumptionFillingTank }, // Water Consumption Filling Tank
            { "id": "111", "qc": 3, "ts": currentDate, "val": signals_energyConsumptionHeatingTank }, // Energy Consumption Heating Tank
            { "id": "112", "qc": 3, "ts": currentDate, "val": signals_energyConsumptionFillingBottle }, // Energy Consumption Filling Bottles
            { "id": "113", "qc": 3, "ts": currentDate, "val": signals_gasConsumptionHeatingTank }, // Gas Consumption Heating Tank
            { "id": "114", "qc": 3, "ts": currentDate, "val": signals_alarm }, // Alarm Signal
            { "id": "123", "qc": 3, "ts": currentDate, "val": operate_machineState }, // Machine State
            { "id": "124", "qc": 3, "ts": currentDate, "val": model_cycleTime }, // Cycle Time
            { "id": "148", "qc": 3, "ts": currentDate, "val": process_productId }, // Product ID
            { "id": "149", "qc": 3, "ts": currentDate, "val": process_numberProduced }, // Number Produced
            { "id": "150", "qc": 3, "ts": currentDate, "val": process_numberFaulty }, // Number Faulty
            { "id": "151", "qc": 3, "ts": currentDate, "val": process_numberGood }, // Number Good
            { "id": "152", "qc": 3, "ts": currentDate, "val": process_batchId }, // Batch ID
            { "id": "170", "qc": 3, "ts": currentDate, "val": serialNumber }, // Serial Number (will be updated dynamically)
        ]
    }
};

// Simulation Logic ********************************************************************************************************

switch (state) {
    case "start":
        // Start: Initialize the process by filling the tank
        signals_tankLevel = global.get("GDB.signals.tankSignals.actLevel") || 0;
        state = "filling_tank";
        break;

    case "filling_tank":
        // Fill the tank
        operate_machineState = 1;
        signals_tankLevel += 50;
        signals_energyConsumptionFillingTank += 5;
        signals_waterConsumptionFillingTank += 2;

        if (signals_tankLevel >= maxTankLevel) {
            signals_tankLevel = maxTankLevel;
            signals_tankMaxLevel = true;
            state = "heating_tank";
        }
        break;

    case "heating_tank":
        // Heat the tank
        operate_machineState = 2;
        signals_tankTemperature += 5;
        signals_energyConsumptionHeatingTank += 3;
        signals_gasConsumptionHeatingTank += 1;

        if (signals_tankTemperature >= maxTankTemperature) {
            signals_tankMaxTemperature = true;
            state = "filling_bottle";
        }
        break;

    case "filling_bottle":
        // Fill the bottle
        operate_machineState = 3;


        // Calculate the amount to fill per call (to fill in 3 seconds, called every 0.2 seconds)
        const fillRate = maxBottleLevel / 15;  // 15 iterations in 3 seconds

        // Ensure there's enough liquid in the tank to fill the bottle
        if (signals_tankLevel > 0) {
            let fillAmount = Math.min(fillRate, signals_tankLevel);  // Only fill up to the available liquid in the tank
            signals_bottleLevel += fillAmount;
            signals_tankLevel -= fillAmount;
            signals_energyConsumptionFillingBottle += (fillAmount > 0) ? 2 : 0;  // Only increase energy if filling happens
        } else {
            signals_tankLevel = 0;  // Ensure tank level doesn't go negative
            state = "filling_tank"; // Switch to filling tank if empty
            break;  // Exit the current state since we can't fill the bottle anymore
        }

        // Check if the bottle is full
        if (signals_bottleLevel >= maxBottleLevel) {
            signals_bottleLevel = maxBottleLevel;  // Ensure bottle doesn't overfill
            process_numberProduced++;  // Increment the number of produced bottles
            signals_bottleMaxLevel = true;  // Indicate that the bottle is full
            state = "shifting_bottle";  // Move to the next step of shifting the bottle
        }
        break;

    case "shifting_bottle":
        // Ensure that the machine state for shifting the bottle is set
        operate_machineState = 4;

        // Increment the counter (called every 0.2 seconds)
        shiftCounter++;

        //Set productID
        process_productId = process_numberProduced + 1;

        // Wait for 2 seconds (10 iterations of 0.2 seconds)
        if (shiftCounter >= 10) {
            // Bottle shifting is complete after 2 seconds
            signals_bottleOutputTank = signals_bottleLevel;  // Transfer the bottle to output
            signals_bottleLevel = 0;  // Reset the bottle level
            signals_bottleMaxLevel = false;  // Reset the max level flag

            // Randomly decide if the bottle is faulty or good (10% chance of faulty)
            if (Math.random() < 0.1) {
                process_numberFaulty++;  // Increment faulty bottle count
            } else {
                process_numberGood++;  // Increment good bottle count
            }

            // Generate the serial number for the bottle at the start of this process
            const currentDateObj = new Date();
            const year = currentDateObj.getFullYear();
            const month = String(currentDateObj.getMonth() + 1).padStart(2, '0');
            const day = String(currentDateObj.getDate()).padStart(2, '0');
            const time = currentDateObj.toTimeString().split(' ')[0];  // Extract the time portion as HH:MM:SS
            serialNumber = `${year}.${month}.${day}/${time}/${process_batchId}/${process_productId}`;



            state = "filling_bottle";  // Move to the next bottle filling process
            shiftCounter = 0;  // Reset the counter for the next shifting process
        }
        break;

    case "stop":
        // Stop state triggered by an alarm/fault
        operate_machineState = 5;
        break;

    case "reset":
        // Reset process to start over
        operate_machineState = 6;
        process_numberProduced = 0;
        process_numberGood = 0;
        process_numberFaulty = 0;
        state = "stop";
        break;

    default:
        state = "start";
        break;
}

// Store the updated state and values back to the global context
global.set("state", state);
global.set("GDB.signals.alarm", signals_alarm);
global.set("GDB.signals.energySignals.energyConsumptionFillingTank", signals_energyConsumptionFillingTank);
global.set("GDB.signals.energySignals.waterConsumptionFillingTank", signals_waterConsumptionFillingTank);
global.set("GDB.signals.energySignals.energyConsumptionHeatingTank", signals_energyConsumptionHeatingTank);
global.set("GDB.signals.energySignals.energyConsumptionFillingBottles", signals_energyConsumptionFillingBottle);
global.set("GDB.signals.energySignals.gasConsumptionHeatingTank", signals_gasConsumptionHeatingTank);
global.set("GDB.signals.tankSignals.actLevel", signals_tankLevel);
global.set("GDB.signals.tankSignals.maxLevel", signals_tankMaxLevel);
global.set("GDB.signals.tankSignals.actPressure", signals_tankPressure);
global.set("GDB.signals.tankSignals.actTemperature", signals_tankTemperature);
global.set("GDB.signals.tankSignals.maxTemperature", signals_tankMaxTemperature);
global.set("GDB.signals.bottleSignals.actLevel", signals_bottleLevel);
global.set("GDB.signals.bottleSignals.maxLevel", signals_bottleMaxLevel);
global.set("GDB.signals.bottleSignals.outputTank", signals_bottleOutputTank);
global.set("GDB.operate.machineState", operate_machineState);
global.set("GDB.model.cycleTime", model_cycleTime);
global.set("GDB.process.productId", process_productId);
global.set("GDB.process.numberProduced", process_numberProduced);
global.set("GDB.process.numberFaulty", process_numberFaulty);
global.set("GDB.process.numberGood", process_numberGood);
global.set("GDB.process.batchId", process_batchId);
global.set("shiftCounter", shiftCounter);
global.set("GDB.serialNumber", serialNumber);

// Return the StateMsg as the output of the node
return StateMsg;
